// Temporary parity harness: compares the native Go embedder and reranker
// against reference outputs generated by the Python workers.
package main

import (
	"context"
	"encoding/json"
	"fmt"
	"math"
	"os"

	"github.com/berzz26/recall/services/api/internal/embedding"
	"github.com/berzz26/recall/services/api/internal/rerank"
	"github.com/sugarme/tokenizer"
	"github.com/sugarme/tokenizer/pretrained"
)

type reference struct {
	Passages          []string           `json:"passages"`
	PassageEmbeddings [][]float32        `json:"passage_embeddings"`
	Queries           []string           `json:"queries"`
	QueryEmbeddings   [][]float32        `json:"query_embeddings"`
	RerankQuery       string             `json:"rerank_query"`
	RerankDocs        []string           `json:"rerank_docs"`
	RerankScores      map[string]float64 `json:"rerank_scores"`
}

func cos(a, b []float32) float64 {
	var dot, na, nb float64
	for i := range a {
		dot += float64(a[i]) * float64(b[i])
		na += float64(a[i]) * float64(a[i])
		nb += float64(b[i]) * float64(b[i])
	}
	return dot / (math.Sqrt(na) * math.Sqrt(nb))
}

func main() {
	raw, err := os.ReadFile("/tmp/opencode/parity_ref.json")
	if err != nil {
		panic(err)
	}
	var ref reference
	if err := json.Unmarshal(raw, &ref); err != nil {
		panic(err)
	}
	ctx := context.Background()

	e := embedding.NewNativeEmbedder(embedding.NativeOptions{
		ONNXDir:     "workers/embedding/models/bge-small-en-v1.5",
		RuntimePath: "third_party/onnxruntime/onnxruntime-linux-x64-1.31.1/lib/libonnxruntime.so",
		ONNXThreads: 4,
		BatchSize:   32,
	})
	if err := e.Load(); err != nil {
		panic(err)
	}
	defer e.Close()

	maxCos, maxDiff := 0.0, 0.0
	vecs, err := e.EmbedPassages(ctx, ref.Passages)
	if err != nil {
		panic(err)
	}
	for i := range vecs {
		c := cos(vecs[i], ref.PassageEmbeddings[i])
		if 1-c > maxCos {
			maxCos = 1 - c
		}
		for j := range vecs[i] {
			d := math.Abs(float64(vecs[i][j] - ref.PassageEmbeddings[i][j]))
			if d > maxDiff {
				maxDiff = d
			}
		}
	}
	fmt.Printf("passage embeddings: max(1-cos)=%.10f max_abs_diff=%.10f\n", maxCos, maxDiff)
	for i := range ref.Queries {
		qv, err := e.EmbedQuery(ctx, ref.Queries[i])
		if err != nil {
			panic(err)
		}
		fmt.Printf("query %d: cos=%.8f\n", i, cos(qv, ref.QueryEmbeddings[i]))
	}

	r := rerank.NewNativeReranker(rerank.NativeOptions{
		ModelName:    "mixedbread-ai/mxbai-rerank-xsmall-v1",
		Quantization: "int8",
		ONNXDir:      "workers/rerank/models/mxbai-rerank-xsmall-v1",
		RuntimePath:  "third_party/onnxruntime/onnxruntime-linux-x64-1.31.1/lib/libonnxruntime.so",
		ONNXThreads:  4,
		BatchSize:    5,
	})
	if err := r.Load(); err != nil {
		panic(err)
	}
	defer r.Close()
	scores, err := r.Rerank(ctx, ref.RerankQuery, ref.RerankDocs)
	if err != nil {
		panic(err)
	}
	fmt.Println("rerank scores (go vs py):")
	maxScoreDiff := 0.0
	for i, s := range scores {
		py := ref.RerankScores[fmt.Sprintf("doc-%d", i)]
		d := math.Abs(s - py)
		if d > maxScoreDiff {
			maxScoreDiff = d
		}
		fmt.Printf("  doc-%d: go=%.6f py=%.6f diff=%.6f\n", i, s, py, d)
	}
	fmt.Printf("rerank max_score_diff=%.8f\n", maxScoreDiff)

	// Tokenization parity vs transformers AutoTokenizer pair encoding.
	if tokRaw, err := os.ReadFile("/tmp/opencode/tok_ref.json"); err == nil {
		var tokRef map[string]map[string][]int
		if err := json.Unmarshal(tokRaw, &tokRef); err == nil {
			tok, terr := pretrained.FromFile("workers/rerank/models/mxbai-rerank-xsmall-v1/tokenizer.json")
			if terr != nil {
				panic(terr)
			}
			tok.WithTruncation(&tokenizer.TruncationParams{MaxLength: 512, Strategy: tokenizer.LongestFirst})
			pairs := [][2]string{
				{ref.RerankQuery, ref.RerankDocs[0]},
				{ref.RerankQuery, ref.RerankDocs[1]},
				{ref.RerankQuery, " "},
			}
			for i, p := range pairs {
				enc, terr := tok.Encode(tokenizer.NewDualEncodeInput(
					tokenizer.NewInputSequence(p[0]),
					tokenizer.NewInputSequence(p[1]),
				), true)
				if terr != nil {
					panic(terr)
				}
				refIDs := tokRef[fmt.Sprintf("pair%d", i)]["input_ids"]
				match := len(enc.Ids) == len(refIDs)
				if match {
					for j := range enc.Ids {
						if int(enc.Ids[j]) != refIDs[j] {
							match = false
							break
						}
					}
				}
				fmt.Printf("tokens pair%d: len_go=%d len_py=%d match=%v\n", i, len(enc.Ids), len(refIDs), match)
				if !match {
					fmt.Printf("  go=%v\n  py=%v\n", enc.Ids, refIDs)
				}
			}
		}
	}
}
